function countSyllables(word){
  word=word.toLowerCase().replace(/[^a-z]/g,'');
  if(word.length===0) return 0;
  if(word.length<=3) return 1;
  word=word.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/,'');
  word=word.replace(/^y/,'');
  var m=word.match(/[aeiouy]+/g);
  return m?m.length:1;
}
function countWords(text){ var m=text.trim().match(/\S+/g); return m?m.length:0; }
function countSentences(text){ var n=(text.match(/[.!?]+/g)||[]).length; return n>0?n:1; }
function fleschReadingEase(text){
  var w=countWords(text), s=countSentences(text), syl=0;
  (text.match(/\S+/g)||[]).forEach(function(x){ syl+=countSyllables(x); });
  if(w===0) return {error:'empty', score:0};
  var score=206.835 - 1.015*(w/s) - 84.6*(syl/w);
  return {words:w, sentences:s, syllables:syl, score:Math.round(score*10)/10, error:null};
}
function fleschKincaidGrade(text){
  var w=countWords(text), s=countSentences(text), syl=0;
  (text.match(/\S+/g)||[]).forEach(function(x){ syl+=countSyllables(x); });
  if(w===0) return {error:'empty'};
  var grade=0.39*(w/s)+11.8*(syl/w)-15.59;
  return {grade:Math.round(grade*10)/10, words:w, sentences:s, syllables:syl, error:null};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { countSyllables:countSyllables, countWords:countWords, countSentences:countSentences,
    fleschReadingEase:fleschReadingEase, fleschKincaidGrade:fleschKincaidGrade };
}
if (typeof window !== 'undefined') {
  window.ReadForgePure = { countSyllables:countSyllables, countWords:countWords, countSentences:countSentences,
    fleschReadingEase:fleschReadingEase, fleschKincaidGrade:fleschKincaidGrade };
}
